def set_interest_rate_C6(interest_code: str):
    """Sets interest rate based on code."""
    ws_interest_rate = Decimal('0.0')
    if interest_code == 'A':
        ws_interest_rate = Decimal('2.0')
    else:
        ws_interest_rate = Decimal('2.5')
    return ws_interest_rate

def calculate_simple_interest_C6(ws_account_balance: Decimal, ws_interest_rate: Decimal, ws_days_in_period: int) -> Decimal:
    """Calculates simple interest."""
    ws_simple_interest = (ws_account_balance * ws_interest_rate * ws_days_in_period) / Decimal('36500.0')
    return ws_simple_interest

def calculate_compound_interest_C6(ws_account_balance: Decimal, ws_interest_rate: Decimal, ws_days_in_period: int) -> Decimal:
    """Calculates compound interest."""
    ws_compound_factor = (1 + ws_interest_rate / Decimal('36500.0')) ** ws_days_in_period
    ws_compound_interest = ws_account_balance * (ws_compound_factor - 1)
    return ws_compound_interest

def apply_interest_C6(ws_interest_method: str, ws_simple_interest: Decimal, ws_compound_interest: Decimal, ws_account_balance: Decimal) -> Decimal:
    """Applies interest to account balance."""
    if ws_interest_method == 'S':
        ws_account_balance += ws_simple_interest
    else:
        ws_account_balance += ws_compound_interest
    update_account_C6()
    return ws_account_balance

def fee_processing_C6():
    """Processes fees."""
    calculate_monthly_fee_C6()
    calculate_transaction_fees_C6()
    apply_fee_waivers_C6()
    deduct_fees_C6()

def calculate_monthly_fee_C6(ws_account_type: str) -> Decimal:
    """Calculates monthly fee based on account type."""
    ws_monthly_fee = Decimal('0.00')
    if ws_account_type == 'CHK':
        ws_monthly_fee = Decimal('12.00')
    elif ws_account_type == 'SAV':
        ws_monthly_fee = Decimal('5.00')
    elif ws_account_type == 'PRM':
        ws_monthly_fee = Decimal('25.00')
    else:
        ws_monthly_fee = Decimal('0.00')
    return ws_monthly_fee

def calculate_transaction_fees_C6(ws_trans_count: int, ws_free_trans_limit: int, ws_per_trans_fee: Decimal) -> Decimal:
    """Calculates transaction fees."""
    ws_trans_fee = Decimal('0.00')
    if ws_trans_count > ws_free_trans_limit:
        ws_excess_trans = ws_trans_count - ws_free_trans_limit
        ws_trans_fee = ws_excess_trans * ws_per_trans_fee
    else:
        ws_trans_fee = Decimal('0.00')
    return ws_trans_fee

def apply_fee_waivers_C6(ws_account_balance: Decimal, ws_min_balance_waiver: Decimal, ws_customer_tier: str, ws_trans_fee: Decimal, ws_monthly_fee: Decimal) -> tuple[Decimal, Decimal]:
    """Applies fee waivers based on balance and customer tier."""
    if ws_account_balance >= ws_min_balance_waiver:
        ws_monthly_fee = Decimal('0.00')
    if ws_customer_tier == 'GOLD' or ws_customer_tier == 'PLATINUM':
        ws_trans_fee = ws_trans_fee * Decimal('0.5')
    return ws_trans_fee, ws_monthly_fee

def deduct_fees_C6(ws_monthly_fee: Decimal, ws_trans_fee: Decimal, ws_account_balance: Decimal):
    """Deducts fees from account balance."""
    ws_total_fees = ws_monthly_fee + ws_trans_fee
    ws_account_balance -= ws_total_fees
    update_account_C6()
    record_fee_transaction_C6()
    return ws_account_balance

def record_fee_transaction_C6():
    """Records fee transaction."""
    initialize_ws_fee_record_C6()
    fee_account = txn_account_id_C6()
    fee_amount = ws_total_fees_C6()
    fee_description = 'MONTHLY FEE'
    fee_date = current_date_function_C6()
    write_fee_record_from_ws_fee_record_C6()

