def collect_transaction_metrics_C10():
    """Collects transaction metrics."""
    ws_total_trans_amount: Decimal = Decimal(0)
    ws_total_trans_count: int = 0
    ws_avg_trans_amount: Decimal = Decimal(0)
    ws_eof_flag: str = 'N'
    transaction_file: list[dict] = []
    ws_trans_rec: dict = {}
    trans_amount: Decimal = Decimal(0)

    while ws_eof_flag != 'Y':
        try:
            ws_trans_rec = transaction_file.pop(0)
            trans_amount = Decimal(ws_trans_rec.get('trans_amount', 0))
            ws_total_trans_count += 1
            ws_total_trans_amount += trans_amount
        except IndexError:
            ws_eof_flag = 'Y'

    if ws_total_trans_count > 0:
        ws_avg_trans_amount = ws_total_trans_amount / ws_total_trans_count
    ws_eof_flag = 'N'

def collect_customer_metrics_C10():
    """Collects customer metrics."""
    ws_active_customers: int = 0
    ws_new_customers: int = 0
    ws_churned_customers: int = 0
    ws_eof_flag: str = 'N'
    customer_file: list[dict] = []
    ws_cust_rec: dict = {}
    cust_status: str = ''
    cust_open_date: Any
    ws_period_start: Any
    cust_close_date: Any

    while ws_eof_flag != 'Y':
        try:
            ws_cust_rec = customer_file.pop(0)
            cust_status = ws_cust_rec.get('cust_status', '')
            cust_open_date = ws_cust_rec.get('cust_open_date')
            cust_close_date = ws_cust_rec.get('cust_close_date')

            if cust_status == 'A':
                ws_active_customers += 1
            if cust_open_date >= ws_period_start:
                ws_new_customers += 1
            if cust_close_date >= ws_period_start:
                ws_churned_customers += 1
        except IndexError:
            ws_eof_flag = 'Y'
    ws_eof_flag = 'N'

def collect_performance_metrics_C10():
    """Collects performance metrics."""
    ws_response_time_total: Decimal = Decimal(0)
    ws_response_count: int = 0
    ws_avg_response_time: Decimal = Decimal(0)
    ws_eof_flag: str = 'N'
    perf_log_file: list[dict] = []
    ws_perf_rec: dict = {}
    perf_response_time: Decimal = Decimal(0)

    while ws_eof_flag != 'Y':
        try:
            ws_perf_rec = perf_log_file.pop(0)
            perf_response_time = Decimal(ws_perf_rec.get('perf_response_time', 0))

            ws_response_time_total += perf_response_time
            ws_response_count += 1
        except IndexError:
            ws_eof_flag = 'Y'

    if ws_response_count > 0:
        ws_avg_response_time = ws_response_time_total / ws_response_count
    ws_eof_flag = 'N'

