def process_shipping_C11() -> None:
    """Processes shipping."""
    global SHIP_METHOD, SHIP_EST_DELIVERY
    if True: #  Implied IF statement based on MOVEs
        SHIP_METHOD = 'EXPRESS'
        SHIP_EST_DELIVERY = int(datetime.datetime.strptime(WS_PROCESS_DATE, "%Y%m%d").toordinal()) + 2
    else:
        SHIP_METHOD = 'STANDARD'
        SHIP_EST_DELIVERY = int(datetime.datetime.strptime(WS_PROCESS_DATE, "%Y%m%d").toordinal()) + 7
    # WRITE shipment_record FROM ws_shipment_record
    pass

def card_blocking_C11() -> None:
    """Blocks a card."""
