def calculate_liquidity_ratios_C13() -> None:
    """Calculates key liquidity ratios."""
    calculate_lcr_C13()
    calculate_nsfr_C13()
    calculate_basic_ratio_C13()

def calculate_lcr_C13() -> None:
    """Calculates the Liquidity Coverage Ratio (LCR)."""
    sum_hqla_C13()
    calculate_net_outflows_C13()
    global ws_lcr_ratio, ws_lcr_numerator, ws_lcr_denominator
    if ws_lcr_denominator > 0:
        ws_lcr_ratio = (ws_lcr_numerator / ws_lcr_denominator) * 100

def sum_hqla_C13() -> None:
    """Sums High-Quality Liquid Assets (HQLA)."""
    global ws_lcr_numerator
    ws_lcr_numerator = Decimal("0.00")
    ws_eof_flag = 'N'
    while ws_eof_flag != 'Y':
        # Read investment_file into ws_inv_rec
        # Assuming investment_file and ws_inv_rec are defined elsewhere
        try:
            inv_hqla_level = "SOME_LEVEL" # Assuming inv_hqla_level is an attribute
            inv_market_value = Decimal("0.00")
            if inv_hqla_level == '1':
                ws_lcr_numerator += inv_market_value
            elif inv_hqla_level == '2A':
                ws_adjusted_value = inv_market_value * Decimal("0.85")
                ws_lcr_numerator += ws_adjusted_value
            elif inv_hqla_level == '2B':
                ws_adjusted_value = inv_market_value * Decimal("0.50")
                ws_lcr_numerator += ws_adjusted_value
        except EOFError:
            ws_eof_flag = 'Y'
    ws_eof_flag = 'N'

def calculate_net_outflows_C13() -> None:
    """Calculates net cash outflows."""
    global ws_total_outflows, ws_total_inflows, ws_lcr_denominator
    ws_total_outflows = Decimal("0.00")
    ws_total_inflows = Decimal("0.00")
    global ws_stable_deposits, ws_less_stable_deposits
    ws_retail_outflow = ws_stable_deposits * Decimal("0.03") + ws_less_stable_deposits * Decimal("0.10")
    global ws_operational_deposits, ws_non_operational
    ws_wholesale_outflow = ws_operational_deposits * Decimal("0.25") + ws_non_operational * Decimal("0.40")
    ws_total_outflows += ws_retail_outflow
    ws_total

