    icd_to = ws_search_to
    icd_amount = ws_ic_diff
    ws_ic_diff_rec['from'] = icd_from
    ws_ic_diff_rec['to'] = icd_to
    ws_ic_diff_rec['amount'] = icd_amount
    ic_diff_record = ws_ic_diff_rec
