def rotate_encryption_key_C15() -> None:
    """Rotate encryption key."""
    ws_key_age_days = 91
    ws_new_key = "NEWKEY"
    ws_encryption_key = "OLDKEY"
    if ws_key_age_days > 90:
        genkey(ws_new_key)
        ws_old_key = ws_encryption_key
        ws_encryption_key = ws_new_key
        reencrypt_data_C15()

def reencrypt_data_C15() -> None:
    """Re-encrypt data with new encryption key."""
    ws_eof_flag: str = 'N'
    ws_encryption_key = "KEY"
    ws_old_key = "OLD"

    while ws_eof_flag != 'Y':
        try:
            encrypted_data_file = {}
            ws_enc_record = encrypted_data_file
            enc_data = "ENCDATA"
            aes256dec(enc_data, ws_old_key)
            ws_decrypted_data = "DECRYPTED"
            aes256enc(ws_decrypted_data, ws_encryption_key)
            ws_reencrypted_data = "REENCRYPTED"
        except FileNotFoundError:
            ws_eof_flag = 'Y'
            break
        else:
            enc_data = ws_reencrypted_data
            # rewrite_encrypted_data_record(ws_enc_record)
            ws_eof_flag = 'N'
    ws_eof_flag = 'N'

